"use client"

import { useEffect, useRef, useState, type CSSProperties, type FormEvent, type PointerEvent, type ReactNode } from "react"

/*
 * Murmur — a dark, single-page landing for a voice-first AI phone app, designed and built by
 * Kedhareswer. The phone screens are HTML laid over a photograph of a hand; that photo, the
 * six portraits and the three glass shapes are generated pictures served from the component
 * site. The voice orb is a canvas and the in-app "artworks" are painted on a canvas at mount.
 * Two small font subsets are embedded (Manrope and Inter, SIL OFL 1.1).
 */

// #region motion
/** The curve every reveal runs on: a quick ease-out that overshoots by a hair. */
export const EASE = "cubic-bezier(.21,.99,.33,1.04)"
/** The two phones tip up on a softer curve. */
export const EASE_TIP = "cubic-bezier(.04,.71,.31,.96)"
/** Heading text: each letter (or word) waits 0.1 s, then starts 40 ms after the one before and runs 1 s. */
export const TEXT = { start: 0.1, stagger: 0.04, dur: 1, y: 30, blur: 5 }
/** Bento cards swing up from -50deg over 1.1 s (the image fan takes 1.2 s), each on its own delay. */
export const CARD_DELAY = { threads: 0.3, studio: 0.4, fan: 0.2, voice: 0.3, group: 0.5 }
/** The slider settles like an overdamped spring (stiffness 200, damping 40), sampled into linear(). */
export const SLIDE =
  "linear(0,0.073,0.204,0.335,0.449,0.546,0.626,0.692,0.747,0.792,0.829,0.859,0.884,0.905,0.922,0.935,0.947,0.956,0.964,0.97,0.976,0.98,0.984,0.986,0.989,0.991,0.992,0.994,0.995,0.996,1)"
const clamp01 = (v: number) => Math.min(1, Math.max(0, v))
/** Hero headline sinks to y 600 and fades to 0.3 while the hero scrolls away (69 px of slack first). */
export function heroSink(scroll: number) {
  const p = clamp01((scroll - 69) / 1703)
  return { y: 600 * p, o: 1 - 0.7 * p }
}
/** Progress of the glass shapes' drift: starts when the section top is 550 px into the viewport, lasts 1075 px. */
export function glassProgress(top: number) {
  return clamp01((550 - top) / 1075)
}
/** Where each glass shape ends up at full drift. */
export const GLASS_TO: { x: number; y: number; r: number }[] = [
  { x: 10, y: 110, r: 0 },
  { x: -50, y: 110, r: -12 },
  { x: -10, y: 60, r: -23 },
]
/** Index of the centre closest to mid. */
export function nearest(centers: number[], mid: number) {
  let best = 0
  for (let i = 1; i < centers.length; i++) if (Math.abs(centers[i] - mid) < Math.abs(centers[best] - mid)) best = i
  return best
}
/** The slider is three copies of the slides; after a move it hops back to the middle copy. */
export function recentre(pos: number, n: number) {
  return pos < n ? pos + n : pos >= 2 * n ? pos - n : pos
}
/** How many slides a drag of dx px (slide pitch w) should move. */
export function dragSteps(dx: number, w: number) {
  if (Math.abs(dx) < 12 || w <= 0) return 0
  return -Math.sign(dx) * Math.max(1, Math.round(Math.abs(dx) / w))
}
// #endregion

