/* ------------------------------------------------------------- painted pictures */

const ART_CACHE: Record<number, string> = {}
function rng(seed: number) {
  let a = seed >>> 0
  return () => {
    a = (a + 0x6d2b79f5) >>> 0
    let t = a
    t = Math.imul(t ^ (t >>> 15), t | 1)
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61)
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }
}
const HUES = ["#8b5cf6", "#ff7a59", "#2dd4bf", "#f5c46b", "#f472b6", "#60a5fa", "#c084fc"]
/** Paints an iridescent glass sculpture: glow, a lumpy glossy body and a specular streak. */
function paintArt(seed: number) {
  if (ART_CACHE[seed]) return ART_CACHE[seed]
  const S = 320
  const cv = document.createElement("canvas")
  cv.width = S
  cv.height = S
  const g = cv.getContext("2d")
  if (!g) return ""
  const r = rng(seed * 7919 + 13)
  const bg = g.createLinearGradient(0, 0, S, S)
  bg.addColorStop(0, "#b7b0ff")
  bg.addColorStop(1, "#f3bfe0")
  g.fillStyle = bg
  g.fillRect(0, 0, S, S)
  for (let i = 0; i < 4; i++) {
    const x = S * (0.2 + r() * 0.6)
    const y = S * (0.2 + r() * 0.6)
    const rad = S * (0.25 + r() * 0.3)
    const gr = g.createRadialGradient(x, y, 0, x, y, rad)
    gr.addColorStop(0, HUES[Math.floor(r() * HUES.length)] + "88")
    gr.addColorStop(1, "#00000000")
    g.fillStyle = gr
    g.fillRect(0, 0, S, S)
  }
  const cx = S * (0.42 + r() * 0.16)
  const cy = S * (0.44 + r() * 0.14)
  const pts: [number, number][] = []
  const n = 9
  for (let i = 0; i < n; i++) {
    const a = (i / n) * Math.PI * 2
    const rr = S * (0.2 + r() * 0.14)
    pts.push([cx + Math.cos(a) * rr, cy + Math.sin(a) * rr * (0.8 + r() * 0.4)])
  }
  const body = () => {
    g.beginPath()
    for (let i = 0; i <= n; i++) {
      const p = pts[i % n]
      const q = pts[(i + 1) % n]
      const mx = (p[0] + q[0]) / 2
      const my = (p[1] + q[1]) / 2
      if (i === 0) g.moveTo(mx, my)
      else g.quadraticCurveTo(p[0], p[1], mx, my)
    }
    g.closePath()
  }
  const h1 = HUES[Math.floor(r() * HUES.length)]
  const h2 = HUES[Math.floor(r() * HUES.length)]
  const lg = g.createLinearGradient(cx - S * 0.3, cy - S * 0.3, cx + S * 0.3, cy + S * 0.3)
  lg.addColorStop(0, "#ffffff")
  lg.addColorStop(0.22, h1)
  lg.addColorStop(0.6, h2)
  lg.addColorStop(1, "#1a1040")
  const gl = g.createRadialGradient(cx, cy, S * 0.12, cx, cy, S * 0.46)
  gl.addColorStop(0, h1 + "66")
  gl.addColorStop(1, "#00000000")
  g.fillStyle = gl
  g.fillRect(0, 0, S, S)
  body()
  g.fillStyle = lg
  g.fill()
  g.save()
  body()
  g.clip()
  const sp = g.createRadialGradient(cx - S * 0.08, cy - S * 0.12, 0, cx - S * 0.08, cy - S * 0.12, S * 0.16)
  sp.addColorStop(0, "rgba(255,255,255,.9)")
  sp.addColorStop(1, "rgba(255,255,255,0)")
  g.fillStyle = sp
  g.fillRect(0, 0, S, S)
  g.strokeStyle = "rgba(255,255,255,.35)"
  g.lineWidth = 3
  for (let i = 0; i < 3; i++) {
    g.beginPath()
    g.arc(cx + S * 0.05, cy + S * 0.06, S * (0.1 + i * 0.07), Math.PI * 1.05, Math.PI * 1.6)
    g.stroke()
  }
  g.restore()
  g.lineWidth = 1.5
  g.strokeStyle = "rgba(255,255,255,.45)"
  body()
  g.stroke()
  const url = cv.toDataURL("image/jpeg", 0.86)
  ART_CACHE[seed] = url
  return url
}
function useArt(seeds: number[]) {
  const [urls, setUrls] = useState(seeds.map(() => ""))
  const key = seeds.join(",")
  useEffect(() => {
    // One painting per task, so the load animation never waits on the canvas work.
    const list = key.split(",").map(Number)
    const next = list.map(() => "")
    let i = 0
    let timer = 0
    const tick = () => {
      if (i >= list.length) return
      next[i] = paintArt(list[i])
      i++
      setUrls(next.slice())
      timer = window.setTimeout(tick, 40)
    }
    timer = window.setTimeout(tick, 60)
    return () => window.clearTimeout(timer)
  }, [key])
  return urls
}
/** The voice orb: nine glowing rings turning through 3D, a slow hexagram and a warm/cool halo. */
function Orb({ still }: { still: boolean }) {
  const ref = useRef(null as HTMLCanvasElement | null)
  useEffect(() => {
    const cv = ref.current
    if (!cv) return
    const ctx = cv.getContext("2d")
    if (!ctx) return
    let raf = 0
    let vis = false
    let w = 0
    const t0 = performance.now()
    const size = () => {
      const b = cv.getBoundingClientRect()
      const d = Math.min(2, window.devicePixelRatio || 1)
      w = Math.max(2, Math.round(Math.min(b.width, b.height) * d))
      cv.width = w
      cv.height = w
    }
    const draw = (t: number) => {
      const c = w / 2
      const R = w * 0.33 * (1 + 0.025 * Math.sin(t * 2.1))
      ctx.clearRect(0, 0, w, w)
      ctx.globalCompositeOperation = "lighter"
      const halo = (x: number, y: number, rad: number, col: string) => {
        const g = ctx.createRadialGradient(x, y, 0, x, y, rad)
        g.addColorStop(0, col)
        g.addColorStop(1, "rgba(0,0,0,0)")
        ctx.fillStyle = g
        ctx.fillRect(0, 0, w, w)
      }
      halo(c - R * 0.35, c - R * 0.3, R * 1.3, "rgba(255,110,80,.16)")
      halo(c + R * 0.35, c + R * 0.35, R * 1.3, "rgba(90,120,255,.18)")
      halo(c, c, R * 1.05, "rgba(255,255,255,.08)")
      const lw = Math.max(1, w * 0.0065)
      for (let i = 0; i < 9; i++) {
        const tilt = (i / 9) * Math.PI + t * 0.45
        const ry = Math.max(0.6, R * Math.abs(Math.cos(tilt)))
        const hue = i % 3 === 0 ? "255,214,170" : i % 3 === 1 ? "200,190,255" : "255,255,255"
        ctx.beginPath()
        ctx.ellipse(c, c, R, ry, i * 0.69 + t * 0.12, 0, Math.PI * 2)
        // A wide faint pass under a thin bright one reads as glow without shadowBlur's cost.
        ctx.lineWidth = lw * 5
        ctx.strokeStyle = "rgba(" + hue + ",.07)"
        ctx.stroke()
        ctx.lineWidth = lw
        ctx.strokeStyle = "rgba(" + hue + ",.75)"
        ctx.stroke()
      }
      ctx.strokeStyle = "rgba(255,255,255,.28)"
      for (let k = 0; k < 2; k++) {
        ctx.beginPath()
        for (let j = 0; j <= 3; j++) {
          const a = t * 0.2 + k * Math.PI + (j / 3) * Math.PI * 2 - Math.PI / 2
          const x = c + Math.cos(a) * R * 0.78
          const y = c + Math.sin(a) * R * 0.78
          if (j === 0) ctx.moveTo(x, y)
          else ctx.lineTo(x, y)
        }
        ctx.stroke()
      }
      ctx.globalCompositeOperation = "source-over"
    }
    const loop = (now: number) => {
      draw((now - t0) / 1000)
      if (vis && !still) raf = requestAnimationFrame(loop)
    }
    size()
    draw(1.3)
    const io = new IntersectionObserver((es) => {
      vis = es[0].isIntersecting
      cancelAnimationFrame(raf)
      if (vis && !still) raf = requestAnimationFrame(loop)
    })
    io.observe(cv)
    const ro = new ResizeObserver(() => {
      size()
      draw((performance.now() - t0) / 1000)
    })
    ro.observe(cv)
    return () => {
      cancelAnimationFrame(raf)
      io.disconnect()
      ro.disconnect()
    }
  }, [still])
  return <canvas ref={ref} className="mm-orb" aria-hidden="true" />
}

