export default function MurmurVoiceAppLanding({
  height = "100svh",
  email = "kedhareswer.12110626@gmail.com",
  className,
  style,
}: MurmurVoiceAppLandingProps) {
  const root = useRef(null as HTMLDivElement | null)
  const hero = useRef(null as HTMLElement | null)
  const h1 = useRef(null as HTMLDivElement | null)
  const prem = useRef(null as HTMLDivElement | null)
  const feat = useRef(null as HTMLDivElement | null)
  const view = useRef(null as HTMLDivElement | null)
  const track = useRef(null as HTMLDivElement | null)
  const drag = useRef({ on: false, x: 0, dx: 0 })
  const [ready, setReady] = useState(false)
  const [still, setStill] = useState(false)
  const [open, setOpen] = useState(false)
  const [active, setActive] = useState(0)
  const [lit, setLit] = useState(1)
  const [pos, setPos] = useState(SLIDES.length)
  const [glide, setGlide] = useState(true)
  const [visible, setVisible] = useState(2)
  const [sent, setSent] = useState("")
  const arts = useArt([3, 11, 27, 42, 58, 71, 90])
  const N = SLIDES.length

  useEffect(() => {
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)")
    const onMq = () => setStill(mq.matches)
    onMq()
    mq.addEventListener("change", onMq)
    let r2 = 0
    const r1 = requestAnimationFrame(() => (r2 = requestAnimationFrame(() => setReady(true))))
    return () => {
      mq.removeEventListener("change", onMq)
      cancelAnimationFrame(r1)
      cancelAnimationFrame(r2)
    }
  }, [])

  // In-view reveals play once. Blocks fire as soon as they enter; heading text waits until half of it shows.
  useEffect(() => {
    const el = root.current
    if (!el) return
    const make = (threshold: number) =>
      new IntersectionObserver(
        (es, io) => {
          for (const e of es)
            if (e.isIntersecting) {
              e.target.classList.add("mm-in")
              io.unobserve(e.target)
            }
        },
        { threshold },
      )
    const blocks = make(0)
    const text = make(0.5)
    el.querySelectorAll("[data-rv]").forEach((n) => blocks.observe(n))
    el.querySelectorAll("[data-tx]").forEach((n) => text.observe(n))
    return () => {
      blocks.disconnect()
      text.disconnect()
    }
  }, [])

  // Scroll-linked pieces: the hero sink, the glass drift and the active feature.
  useEffect(() => {
    let raf = 0
    const tick = () => {
      raf = 0
      const vh = window.innerHeight
      const moving = !window.matchMedia("(prefers-reduced-motion: reduce)").matches
      if (hero.current && h1.current) {
        const { y, o } = heroSink(moving ? -hero.current.getBoundingClientRect().top : 0)
        h1.current.style.transform = y ? "translateY(" + y.toFixed(2) + "px)" : ""
        h1.current.style.opacity = o < 1 ? o.toFixed(4) : ""
      }
      if (prem.current) {
        const p = moving ? glassProgress(prem.current.getBoundingClientRect().top) : 0
        prem.current.querySelectorAll(".mm-glass").forEach((n, i) => {
          const g = GLASS_TO[i % GLASS_TO.length]
          ;(n as HTMLElement).style.transform = p ? "translate(" + (g.x * p).toFixed(1) + "px," + (g.y * p).toFixed(1) + "px) rotate(" + (g.r * p).toFixed(2) + "deg)" : ""
        })
      }
      if (feat.current) {
        let mask = 0
        const c = Array.from(feat.current.querySelectorAll(".mm-fi h3")).map((n, i) => {
          const b = n.getBoundingClientRect()
          if (b.bottom > 70 && b.top < vh) mask |= 1 << i
          return b.top + b.height / 2
        })
        if (c.length) setActive(nearest(c, vh / 2))
        setLit(mask || 1)
      }
      setVisible(window.innerWidth < 810 ? 1 : 2)
    }
    const on = () => {
      if (!raf) raf = requestAnimationFrame(tick)
    }
    tick()
    window.addEventListener("scroll", on, { passive: true })
    window.addEventListener("resize", on)
    return () => {
      cancelAnimationFrame(raf)
      window.removeEventListener("scroll", on)
      window.removeEventListener("resize", on)
    }
  }, [])

  // After a hop back to the middle copy, switch the glide back on.
  useEffect(() => {
    if (glide) return
    let b = 0
    const a = requestAnimationFrame(() => (b = requestAnimationFrame(() => setGlide(true))))
    return () => {
      cancelAnimationFrame(a)
      cancelAnimationFrame(b)
    }
  }, [glide])

  const settle = () => {
    setPos((p) => {
      const q = recentre(p, N)
      if (q !== p) setGlide(false)
      return q
    })
  }
  const step = (d: number) => {
    if (!d) return
    setPos((p) => {
      const q = Math.max(0, Math.min(3 * N - visible, p + d))
      return still ? recentre(q, N) : q
    })
  }
  const setDx = (dx: number) => {
    if (track.current) track.current.style.setProperty("--dx", dx + "px")
  }
  const onDown = (ev: PointerEvent<HTMLDivElement>) => {
    if (ev.button !== 0) return
    drag.current = { on: true, x: ev.clientX, dx: 0 }
    ev.currentTarget.setPointerCapture(ev.pointerId)
    ev.currentTarget.classList.add("mm-grab")
  }
  const onDrag = (ev: PointerEvent<HTMLDivElement>) => {
    const d = drag.current
    if (!d.on) return
    d.dx = ev.clientX - d.x
    if (track.current) track.current.style.transition = "none"
    setDx(d.dx)
  }
  const onUp = (ev: PointerEvent<HTMLDivElement>) => {
    const d = drag.current
    if (!d.on) return
    d.on = false
    ev.currentTarget.classList.remove("mm-grab")
    const first = track.current ? (track.current.firstElementChild as HTMLElement | null) : null
    const w = first ? first.getBoundingClientRect().width + 30 : 0
    if (track.current) track.current.style.transition = ""
    setDx(0)
    step(dragSteps(d.dx, w))
  }

  // A soft light follows a real mouse across the cards. Touch never drives it.
  const onMove = (ev: PointerEvent) => {
    if (ev.pointerType !== "mouse") return
    const card = (ev.target as HTMLElement).closest(".mm-box") as HTMLElement | null
    if (!card) return
    const b = card.getBoundingClientRect()
    card.style.setProperty("--mx", ev.clientX - b.left + "px")
    card.style.setProperty("--my", ev.clientY - b.top + "px")
  }

  const mail = "mailto:" + email
  const submit = (ev: FormEvent<HTMLFormElement>) => {
    ev.preventDefault()
    const v = String(new FormData(ev.currentTarget).get("email") || "").trim()
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v)) {
      setSent("That address doesn’t look right yet.")
      return
    }
    window.location.href = mail + "?subject=" + encodeURIComponent("Murmur beta") + "&body=" + encodeURIComponent("Please add " + v + " to the Murmur beta.")
    setSent("Your mail app has the request ready to send.")
  }
  const dl = (s: number) => ({ "--dl": s + "s" }) as CSSProperties
  const pitch = "((100% - " + (visible - 1) * 30 + "px) / " + visible + " + 30px)"
  const links: [string, string][] = [["Features", "#mm-features"], ["About", "#mm-talk"], ["Plus", "#mm-plus"], ["Contact", "#mm-join"]]
  const fan = ["translate(-58px,10px) rotate(-22deg)", "translate(-40px,4px) rotate(-15deg)", "translate(-22px,0) rotate(-8deg)", "translate(-6px,-2px) rotate(-2deg)", "translate(10px,-2px) rotate(5deg)"]
  const fanHover = ["translate(-82px,18px) rotate(-30deg)", "translate(-56px,8px) rotate(-20deg)", "translate(-30px,0) rotate(-10deg)", "translate(-6px,-4px) rotate(-2deg)", "translate(20px,-4px) rotate(8deg)"]
  const discs = [490, 400, 300]

  return (
    <div ref={root} className={"mm-root" + (ready ? " mm-ready" : "") + (className ? " " + className : "")} style={style} onPointerMove={onMove}>
      <style>{FONTS + CSS}</style>

      <header className={"mm-nav" + (open ? " mm-open" : "")}>
        <div className="mm-navin">
          <a href="#mm-top" className="mm-logo" aria-label="Murmur home"><Mark />murmur.</a>
          <nav className="mm-links" aria-label="Main">
            {links.map(([t, h]) => (
              <a key={t} className="mm-link" href={h}>{t}</a>
            ))}
            <a className="mm-pill" href="#mm-join">Get the app <Ic n="chev" /></a>
          </nav>
          <button className="mm-burger" type="button" aria-label="Menu" aria-expanded={open} onClick={() => setOpen((o) => !o)}><i /><i /></button>
        </div>
        <nav className="mm-menu" aria-label="Mobile" aria-hidden={!open}>
          {links.map(([t, h]) => (
            <a key={t} className="mm-link" href={h} tabIndex={open ? 0 : -1} onClick={() => setOpen(false)}>{t}</a>
          ))}
          <a className="mm-pill" href="#mm-join" tabIndex={open ? 0 : -1} onClick={() => setOpen(false)}>Get the app <Ic n="chev" /></a>
        </nav>
      </header>

      <section id="mm-top" ref={hero} className="mm-hero" style={{ minHeight: height }}>
        <div ref={h1} style={{ willChange: "transform" }}>
          <h1 className="mm-head mm-h1 mm-wrap"><Split lines={["Think Out Loud,", "Beautifully Heard"]} /></h1>
        </div>
        <div className="mm-stagebox">
          <div className="mm-stage">
            <div className="mm-tip">
              <Hand />
              <Phone><ChatScreen arts={arts.slice(0, 3)} /></Phone>
            </div>
          </div>
          <div className="mm-fade" />
        </div>
        <div className="mm-wrap mm-center">
          <p className="mm-hsub mm-rv mm-up" data-rv="" style={dl(0.7)}>
            Kedhareswer built Murmur so you can talk, brainstorm, make images and plan with AI through an interface
            that feels both calm and familiar.
          </p>
          <div className="mm-hcta mm-rv mm-up" data-rv="" style={dl(0.8)}>
            <a className="mm-pill" href="#mm-features" style={{ pointerEvents: "auto" }}>See Features <Ic n="chev" /></a>
          </div>
        </div>
      </section>

      <div className="mm-wrap" data-rv=""><hr className="mm-rule mm-rv mm-pop" /></div>

      <section id="mm-features" className="mm-sec1">
        <div className="mm-wrap">
          <h2 className="mm-head mm-h2 mm-center" data-tx=""><Split lines={["Think Smarter, Together"]} /></h2>
          <div className="mm-bento">
            <div className="mm-bl">
              <div className="mm-box mm-b1 mm-rv mm-card" data-rv="" style={dl(CARD_DELAY.threads)}>
                <h3 className="mm-t">Live Threads</h3>
                <p>Get instant answers, follow tangents and keep every thought connected.</p>
                <Rows n={3} ring />
              </div>
              <div className="mm-box mm-b2 mm-rv mm-card" data-rv="" style={dl(CARD_DELAY.studio)}>
                <div className="mm-fanbox mm-rv mm-card" style={{ ...dl(CARD_DELAY.fan), ["--d" as string]: "1.2s" } as CSSProperties}>
                  {fan.map((t, i) => (
                    <span key={i} style={{ backgroundImage: arts[i + 2] ? "url(" + arts[i + 2] + ")" : undefined, backgroundColor: "#cbbcf5", transform: t, ["--h" as string]: fanHover[i] } as CSSProperties} />
                  ))}
                </div>
                <div className="mm-txt">
                  <h3 className="mm-t">AI images</h3>
                  <p>Turn a spoken idea into striking visuals in seconds.</p>
                </div>
              </div>
              <div className="mm-box mm-b3 mm-rv mm-card" data-rv="" style={dl(CARD_DELAY.voice)}>
                <div className="mm-ask" aria-hidden="true">
                  <div className="mm-ring mm-input"><span>Say your question</span><span className="mm-mic"><Ic n="mic" /></span></div>
                  <small>How to plan Project 01 around my week</small>
                </div>
                <div className="mm-txt">
                  <h3 className="mm-t">Voice Chat</h3>
                  <p>Speak and hear the reply in real time</p>
                </div>
              </div>
            </div>
            <div className="mm-box mm-b4 mm-rv mm-card" data-rv="" style={dl(CARD_DELAY.group)}>
              <h3 className="mm-t">Bring Murmur to your chats.</h3>
              <p>Drop smarter replies into every conversation and keep group threads useful, playful and moving.</p>
              <div className="mm-orbit" aria-hidden="true">
                {discs.map((d, i) => (
                  <i key={d} className="mm-disc" style={{ left: -d / 2, top: -d / 2, width: d, height: d, opacity: [0.1, 0.3, 0.4][i] }} />
                ))}
                {[0, 1, 2].map((ring) => (
                  <div key={ring} className={"mm-spin" + (ring === 1 ? " mm-rev" : "")}>
                    {SATS.map(([r, x, y, s], i) =>
                      r === ring ? (
                        <span key={i} className="mm-sat" style={{ left: x - s / 2, top: y - s / 2, width: s, height: s }}>
                          <Av i={i} s={s + "px"} />
                        </span>
                      ) : null,
                    )}
                  </div>
                ))}
                <div className="mm-ocore"><Orb still={still} /></div>
              </div>
            </div>
          </div>
        </div>
      </section>

      <section className="mm-wrap">
        <div className="mm-feat" ref={feat}>
          <div className="mm-fphone" aria-hidden="true" style={{ gridColumn: 2, gridRow: 1 }}>
            <Phone>
              <VoiceScreen still={still} style={{ opacity: active === 0 ? 1 : 0 }} />
              <ChatScreen arts={arts.slice(4, 7)} style={{ opacity: active === 1 ? 1 : 0 }} />
              <ImageScreen arts={arts.slice(0, 4)} style={{ opacity: active === 2 ? 1 : 0 }} />
              <EditScreen style={{ opacity: active === 3 ? 1 : 0 }} />
              <HistoryScreen style={{ opacity: active === 4 ? 1 : 0 }} />
            </Phone>
          </div>
          <div className="mm-flist" style={{ gridColumn: 1, gridRow: 1 }}>
            {FEATURES.map(([ic, t], i) => (
              <div key={t} className={"mm-fi" + (lit & (1 << i) ? " on" : "")}>
                <span className="mm-ico"><Ic n={ic} /></span>
                <h3 className="mm-head mm-h3">{t}</h3>
              </div>
            ))}
          </div>
        </div>
      </section>

      <section id="mm-talk" className="mm-sec2">
        <div className="mm-wrap">
          <h2 className="mm-head mm-h2" data-tx=""><Split lines={["Hands-free feels like magic"]} /></h2>
          <div className="mm-talk">
            <p className="mm-rv mm-up" data-rv="" style={dl(0.4)}>
              Hold natural, real-time voice conversations with an AI that feels like talking to a friend. Get answers,
              notes and next steps, all hands-free and unhurried.
            </p>
            <a className="mm-pill mm-rv mm-up" data-rv="" style={dl(0.4)} href={mail}>Talk to Kedhareswer <Ic n="chev" /></a>
          </div>
          <div className="mm-slider mm-rv mm-up" data-rv="" style={dl(0.5)} role="region" aria-roledescription="carousel" aria-label="Highlights">
            <div ref={view} className="mm-view" onPointerDown={onDown} onPointerMove={onDrag} onPointerUp={onUp} onPointerCancel={onUp}>
              <div
                ref={track}
                className="mm-track"
                style={{ transform: "translateX(calc(" + -pos + " * " + pitch + " + var(--dx,0px)))", transition: glide && !still ? "transform 1s " + SLIDE : "none" }}
                onTransitionEnd={(ev) => {
                  if (ev.target === ev.currentTarget) settle()
                }}
              >
                {[0, 1, 2].flatMap((copy) =>
                  SLIDES.map(([kind, t, d], i) => {
                    const at = copy * N + i
                    return (
                      <div key={at} className="mm-slide" aria-hidden={at < pos || at >= pos + visible}>
                        <div className="mm-box mm-vcard">
                          {kind === "beams" ? <Beams still={still} /> : kind === "list" ? <ListVis /> : <PhoneVis />}
                          <div className="mm-vtext">
                            <h3 className="mm-t">{t}</h3>
                            <p>{d}</p>
                          </div>
                        </div>
                      </div>
                    )
                  }),
                )}
              </div>
            </div>
            <button className="mm-arrow mm-prev" type="button" aria-label="Previous" onClick={() => step(-1)}><Ic n="left" /></button>
            <button className="mm-arrow mm-next" type="button" aria-label="Next" onClick={() => step(1)}><Ic n="chev" /></button>
          </div>
        </div>
      </section>

      <div className="mm-wrap" data-rv="" style={{ marginTop: 50 }}><hr className="mm-rule mm-rv mm-pop" /></div>

      <section id="mm-plus">
        <div className="mm-wrap mm-prem" ref={prem}>
          {[0, 1, 2].map((n) => (
            <div key={n} className={"mm-glass mm-g" + n} data-rv="">
              <div className="mm-rv mm-tilt" style={{ position: "relative", width: "100%", height: "100%" }}><Glass n={n} /></div>
            </div>
          ))}
          <h2 className="mm-head mm-h3" data-tx=""><Split lines={["Go Further Every Day", "with Murmur Plus"]} words /></h2>
          <p className="mm-lead mm-rv mm-up" data-rv="" style={dl(0.8)}>
            Unlock deeper memory, faster voice and richer image tools, designed by Kedhareswer for people who think
            out loud all day.
          </p>
          <div className="mm-perks">
            <div className="mm-rv mm-up" data-rv="" style={dl(0.9)}>
              <Ic n="coin" />
              <h4 className="mm-t">Priority access</h4>
              <p>Enjoy smoother replies and a steadier, more reliable voice</p>
            </div>
            <div className="mm-rv mm-up" data-rv="" style={dl(1)}>
              <Ic n="tools" />
              <h4 className="mm-t">Advanced tools</h4>
              <p>Reach extended features for voice notes and image styles</p>
            </div>
          </div>
        </div>
      </section>

      <section id="mm-join" className="mm-sec3">
        <div className="mm-wrap mm-center">
          <p className="mm-rv mm-up" data-rv="" style={dl(0.6)}>Ready to talk with Murmur</p>
          <h2 className="mm-head mm-h2 mm-h2c mm-rv mm-up" data-rv="" style={dl(0.7)}>
            Experience the future of AI
            <br />
            conversation with Murmur
          </h2>
          <div className="mm-join" data-rv="">
            <i className="mm-jglow mm-jg2 mm-rv mm-small" />
            <i className="mm-jglow mm-jg1 mm-rv mm-big" />
            <div className="mm-jtext">
              <p className="mm-dim mm-rv mm-up" style={dl(0.8)}>Upgrade the way you think</p>
              <h3 className="mm-head mm-rv mm-up" style={dl(0.8)}>Unlock more from every conversation with Murmur</h3>
              <form className="mm-form mm-rv mm-up" style={dl(0.9)} onSubmit={submit} noValidate>
                <input name="email" type="email" placeholder="Enter E-mail here" aria-label="Email address" autoComplete="email" />
                <button type="submit">Submit</button>
                <p className="mm-note" aria-live="polite">{sent}</p>
              </form>
            </div>
            <div className="mm-jhand mm-rv mm-rise" aria-hidden="true">
              <div className="mm-stage">
                <Hand />
                <Phone><ChatScreen arts={[arts[6], arts[1], arts[2]]} /></Phone>
                </div>
            </div>
          </div>
        </div>
      </section>

      <footer className="mm-foot">
        <div className="mm-fin">
          <div className="mm-fgrid">
            <div>
              <a href="#mm-top" className="mm-logo"><Mark />murmur.</a>
              <p>Murmur brings it all into one calm AI companion, designed and built by Kedhareswer for faster, clearer thinking.</p>
            </div>
            <div className="mm-cols">
              <div>
                <h5>EXPLORE</h5>
                <a href="#mm-top" className="on">Home</a>
                {links.map(([t, h]) => (
                  <a key={t} href={h}>{t}</a>
                ))}
              </div>
              <div>
                <h5>SELECTED WORK</h5>
                <a href="#mm-top">Project 01</a>
                <a href="#mm-top">Project 02</a>
                <a href="#mm-top">Project 03</a>
                <a href={mail}>Email</a>
              </div>
            </div>
          </div>
          <div className="mm-base">
            <p>Created by <span>Kedhareswer</span></p>
            <a href={mail}>Write to <span>{email}</span></a>
          </div>
        </div>
      </footer>
    </div>
  )
}
